-- GENERATED by tools/gen_compat_sql.py from the live column types of CAFC_DB.CORE.PLAYER_INFORMATION. Do not hand-edit.
-- 051_compat_intel.sql
-- The LEGACY-SHAPED compatibility view over the normalized intel tables: same 25 columns, same order, same types,
-- same values as the legacy PLAYER_INFORMATION table. At the swap the legacy table is renamed *_LEGACY and a view
-- with the legacy NAME selects from this, so the app's read queries (and the dbt APP_COMPAT view) are unchanged.
-- Pure view, safe to re-create at any time. Checked against the real legacy table by parity/intel.sql.

CREATE OR REPLACE VIEW ${CORE}.V_COMPAT_PLAYER_INFORMATION AS
WITH deals AS (
    SELECT INTEL_REPORT_ID, LISTAGG(${CORE}.INTEL_DEAL_TYPE_CODE(DEAL_TYPE_CODE), ',') WITHIN GROUP (ORDER BY SEQ) AS V
    FROM ${CORE}.INTEL_DEAL_TYPES GROUP BY INTEL_REPORT_ID
), rels AS (
    SELECT INTEL_REPORT_ID, LISTAGG(RELATIONSHIP_CODE, ',') WITHIN GROUP (ORDER BY SEQ) AS V
    FROM ${CORE}.INTEL_RELATIONSHIPS GROUP BY INTEL_REPORT_ID
), fee AS (
    SELECT * FROM ${CORE}.INTEL_TERMS WHERE TERM_TYPE = 'TRANSFER_FEE'
), cur AS (
    SELECT * FROM ${CORE}.INTEL_TERMS WHERE TERM_TYPE = 'CURRENT_WAGES'
), exp AS (
    SELECT * FROM ${CORE}.INTEL_TERMS WHERE TERM_TYPE = 'EXPECTED_WAGES'
)
SELECT
    CAST(r.ID AS NUMBER(38,0)) AS ID,
    CAST(c.CONTACT_NAME AS VARCHAR) AS CONTACT_NAME,
    CAST(c.CONTACT_ORGANISATION AS VARCHAR) AS CONTACT_ORGANISATION,
    CAST(r.DATE_OF_INFORMATION AS DATE) AS DATE_OF_INFORMATION,
    CAST(r.CONTRACT_EXPIRY AS DATE) AS CONTRACT_EXPIRY,
    CAST(r.CONTRACT_OPTIONS AS VARCHAR) AS CONTRACT_OPTIONS,
    CAST(deals.V AS VARCHAR) AS POTENTIAL_DEAL_TYPE,
    CAST(fee.RAW_TEXT AS VARCHAR) AS TRANSFER_FEE,
    CAST(cur.AMOUNT AS NUMBER(38,0)) AS CURRENT_WAGES,
    CAST(exp.AMOUNT AS NUMBER(38,0)) AS EXPECTED_WAGES,
    CAST(r.CONVERSATION_NOTES AS VARCHAR) AS CONVERSATION_NOTES,
    CAST(r.ACTION_REQUIRED AS VARCHAR) AS ACTION_REQUIRED,
    CAST(r.CREATED_AT AS TIMESTAMP_NTZ) AS CREATED_AT,
    CAST(r.PLAYER_ID AS NUMBER(38,0)) AS PLAYER_ID,
    CAST(r.USER_ID AS NUMBER(38,0)) AS USER_ID,
    CAST(r.DATA_SOURCE AS VARCHAR(10)) AS DATA_SOURCE,
    CAST(exp.AMOUNT_MAX AS NUMBER(18,0)) AS EXPECTED_WAGES_MAX,
    CAST(exp.AMOUNT_MIN AS NUMBER(18,0)) AS EXPECTED_WAGES_MIN,
    CAST(cur.AMOUNT_MAX AS NUMBER(18,0)) AS CURRENT_WAGES_MAX,
    CAST(cur.AMOUNT_MIN AS NUMBER(18,0)) AS CURRENT_WAGES_MIN,
    CAST(r.INTEL_TYPE AS VARCHAR) AS INTEL_TYPE,
    CAST(rels.V AS VARCHAR) AS RELATIONSHIP_TO_PLAYER,
    CAST(ref.LENGTH_OF_RELATIONSHIP AS VARCHAR) AS LENGTH_OF_RELATIONSHIP,
    CAST(ref.RELEVANCE_OF_RELATIONSHIP AS VARCHAR) AS RELEVANCE_OF_RELATIONSHIP,
    CAST(ref.REFERENCE_RATING AS VARCHAR) AS REFERENCE_RATING
FROM ${CORE}.INTEL_REPORTS r
LEFT JOIN ${CORE}.CONTACTS c ON c.CONTACT_ID = r.CONTACT_ID
LEFT JOIN deals ON deals.INTEL_REPORT_ID = r.ID
LEFT JOIN rels  ON rels.INTEL_REPORT_ID  = r.ID
LEFT JOIN fee ON fee.INTEL_REPORT_ID = r.ID
LEFT JOIN cur ON cur.INTEL_REPORT_ID = r.ID
LEFT JOIN exp ON exp.INTEL_REPORT_ID = r.ID
LEFT JOIN ${CORE}.INTEL_REFERENCE_DETAILS ref ON ref.INTEL_REPORT_ID = r.ID;
